// THE 6-STEP FRAMEWORK APPLIED TO A REAL PROBLEM
// Problem: "Find the two numbers in an array that sum to a target."

// STEP 1: CLARIFY (say these out loud)
// - Can there be duplicate numbers? Yes.
// - Is there always exactly one solution? Yes, guaranteed.
// - Can the same element be used twice? No.
// - What are the constraints? nums.length up to 10^4, values -10^9 to 10^9.
// - Return type? Array of two indices [i, j].

// STEP 2: EXAMPLE
// Input: [2, 7, 11, 15], target = 9
// Expected: [0, 1] because nums[0]+nums[1] = 2+7 = 9
// My own example: [3, 2, 4], target = 6 -> [1, 2] because 2+4=6

// STEP 3: BRUTE FORCE
// "Naive approach: try all pairs. O(n^2) time, O(1) space."
function twoSum_brute(nums, target) {
    for (let i = 0; i < nums.length; i++)
        for (let j = i+1; j < nums.length; j++)
            if (nums[i] + nums[j] === target) return [i, j];
    return [];
}

// STEP 4: OPTIMIZE
// "Bottleneck: the inner loop re-scans for the complement.
//  Pattern: use a hash map to look up the complement in O(1).
//  Improved complexity: O(n) time, O(n) space."

// STEP 5: CODE (with verbal commentary)
function twoSum(nums, target) {
    const seen = new Map(); // maps value -> index
    for (let i = 0; i < nums.length; i++) {
        const complement = target - nums[i]; // what we need
        if (seen.has(complement)) {
            return [seen.get(complement), i]; // found: return both indices
        }
        seen.set(nums[i], i); // store current value and index
    }
    return [];
}

// STEP 6: TEST
// Test 1 (given): [2,7,11,15], target=9 -> expected [0,1]
console.log(twoSum([2,7,11,15], 9));  // [0,1] ✓
// Test 2 (my example): [3,2,4], target=6 -> expected [1,2]
console.log(twoSum([3,2,4], 6));      // [1,2] ✓
// Edge: single element: [5], target=5 -> [] (no pair possible)
console.log(twoSum([5], 5));          // [] ✓
// Edge: negative numbers: [-3,4,1], target=1 -> [0,1] (-3+4=1)
console.log(twoSum([-3,4,1], 1));     // [0,1] ✓

// COMPLEXITY STATEMENT (always say this after step 6):
// "Time: O(n) — single pass, O(1) hash map lookup.
//  Space: O(n) — hash map stores up to n elements."

