function isGapClosed(drillResults) {
  if (drillResults.length < 2) return false;
  const last2 = drillResults.slice(-2);
  return last2.every(r => r.score === 5);
}

function isLevel2Complete(sessions) {
  if (sessions.length < 2) return false;
  const recent = sessions.slice(-2);
  return recent.every(s => s.problem1.score >= 4 && s.problem2.score >= 4);
}

function readyForLevel3(sessions, hasAttemptedHard) {
  return isLevel2Complete(sessions) && hasAttemptedHard;
}
